// CR-015: the schema is written twice, in TypeScript here and in Python in services/ingestion. Both sides
// assert against samples/schema.json (generated by `python -m app.contract`), so neither can drift alone.
import assert from "node:assert/strict";
import fs from "node:fs";
import { test } from "node:test";
import { LIMITS } from "./referrals.ts";
import { FIELD_DEFS, REQUIRED_FOR_RATING } from "./submission.ts";
import { UW_AUTHORITY_PCT } from "./worksheet.ts";

const contract = JSON.parse(fs.readFileSync(new URL("../../../samples/schema.json", import.meta.url), "utf8"));

test("the intake form's fields and types match the schema ingestion extracts", () => {
  // money and pct are display variants of int: the extractor stores all three the same way.
  const kind = (type: string) => (type === "money" || type === "pct" ? "int" : type);
  assert.deepEqual(Object.fromEntries(FIELD_DEFS.map((f) => [f.path, kind(f.type)])), contract.fields);
});

test("the fields required for rating match ingestion's list", () => {
  assert.deepEqual(REQUIRED_FOR_RATING, contract.required_for_rating);
});

test("the inbox generator writes every form field ingestion reads", () => {
  const source = fs.readFileSync(new URL("./inbox-generate.ts", import.meta.url), "utf8");
  const names: string[] = [
    ...Object.keys(contract.acord_fields),
    ...contract.loss_columns.map((column: string) => `LossHistory_${column}_`),
  ];
  assert.deepEqual(names.filter((name) => !source.includes(name)), []);
});

test("the schedule authority shown on the workbench is the one the referral rule enforces", () => {
  assert.equal(LIMITS.scheduleAuthorityPct, UW_AUTHORITY_PCT);
});
